function IconButton({icon:Icon,label,onClick,active=false}:{icon:LucideIcon;label:string;onClick:()=>void;active?:boolean}){return <button className={`icon-button ${active?'active':''}`} aria-label={label} title={label} onClick={onClick}><Icon size={19} strokeWidth={1.6}/></button>;}
function Sparkline({values=demo.pain,large=false}:{values?:number[];large?:boolean}){const points=values.map((v,i)=>`${30+i*(640/Math.max(1,values.length-1))},${190-v*15}`).join(' ');return <svg className={large?'trend-chart':'sparkline'} viewBox="0 0 700 210" preserveAspectRatio="none" aria-label="Pain trend"><defs><linearGradient id="chartFill" x1="0" x2="0" y1="0" y2="1"><stop stopColor="#849466" stopOpacity=".2"/><stop offset="1" stopColor="#849466" stopOpacity="0"/></linearGradient></defs>{large&&[0,2,4,6,8,10].map(v=><g key={v}><line x1="30" y1={190-v*15} x2="680" y2={190-v*15} stroke="#e8e8e1" strokeDasharray="3 5"/><text x="0" y={194-v*15} fill="#8c9084" fontSize="12">{v}</text></g>)}<polygon points={`30,200 ${points} 670,200`} fill="url(#chartFill)"/><polyline points={points} stroke="#738456" strokeWidth={large?3:5} fill="none" strokeLinecap="round" strokeLinejoin="round"/>{large&&values.map((v,i)=><circle key={i} cx={30+i*(640/Math.max(1,values.length-1))} cy={190-v*15} r="4" fill="#738456" stroke="#fbfbf7" strokeWidth="2"/>)}</svg>;}
function demoVariant(e:Exercise):string{const fam=e.id.startsWith('upper-back')?'upper':e.id.split('-')[0];if(e.positionRequired==='lying')return 'lie';if(e.positionRequired==='four_point')return 'kneel';if(e.positionRequired==='seated')return fam==='knee'||fam==='ankle'?'sit-leg':fam==='neck'?'sit-neck':'sit';if(fam==='ankle')return 'heel';if(fam==='knee'||fam==='hip')return 'squat';if(fam==='shoulder'||fam==='elbow')return 'raise';if(fam==='neck')return 'neck';return 'hinge';}
const demoLabels:Record<string,string>={heel:'Rise onto your feet, lower with control',squat:'Bend the knees, keep the chest up',raise:'Reach overhead, lower slowly',neck:'Tilt the head gently side to side',hinge:'Hinge at the hips, flat back','sit-leg':'Extend the leg, lower with control',sit:'Sit tall, hinge slightly forward','sit-neck':'Tilt the head gently side to side',lie:'Breathe slowly, let the ribs widen',kneel:'Extend opposite arm and leg, hold steady'};
function ExerciseDemo({exercise,playing}:{exercise:Exercise;playing:boolean}){
 const v=demoVariant(exercise);
 const G={stroke:'#7c8a62',strokeWidth:13,strokeLinecap:'round' as const,fill:'none'};
 const ground=<><ellipse cx="260" cy="210" rx="145" ry="9" fill="#d6ddc8"/><path d="M100 205H407" stroke="#c2cab4" strokeWidth="2"/></>;
 const standLegs=<><path d="M248 130L226 168L220 201"/><path d="M248 130L272 166L280 201"/></>;
 const arrow=<><path d="M330 80q35 30 0 65" stroke="#aab993" strokeWidth="2" strokeDasharray="4 5" fill="none"/><path d="M325 136l5 10 10-6" fill="none" stroke="#aab993" strokeWidth="2"/></>;
 const headStand=<circle cx="245" cy="48" r="20" fill="#e6d5bd" stroke="#b7a68e" strokeWidth="2"/>;
 const stool=<><path d="M196 150H286" stroke="#b9c3a8" strokeWidth="6" strokeLinecap="round"/><path d="M206 154V205M280 154V205" stroke="#b9c3a8" strokeWidth="5" strokeLinecap="round"/></>;
 const figs:Record<string,ReactElement>={
  heel:<g {...G}><g className="v-bob">{headStand}<path d="M245 75L248 130"/>{standLegs}<path d="M245 85L214 108L200 140"/><path d="M245 85L276 108L290 140"/><path d="M220 201L204 202"/><path d="M280 201L296 202"/></g></g>,
  squat:<g {...G}><g className="v-squat"><circle cx="247" cy="58" r="20" fill="#e6d5bd" stroke="#b7a68e" strokeWidth="2"/><path d="M247 84L252 128"/><path d="M247 92L207 97"/><path d="M247 92L289 97"/><path d="M252 128L228 162L222 199"/><path d="M252 128L282 162L292 199"/></g></g>,
  raise:<g {...G}>{headStand}<path d="M245 75L248 130"/>{standLegs}<g className="v-armL"><path d="M245 85L224 58L218 32"/></g><g className="v-armR"><path d="M245 85L266 58L272 32"/></g></g>,
  neck:<g {...G}><g className="v-head">{headStand}</g><path d="M245 75L248 130"/>{standLegs}<path d="M245 85L230 122"/><path d="M245 85L262 122"/></g>,
  hinge:<g {...G}>{standLegs}<g className="v-hinge"><path d="M248 130L245 75"/>{headStand}<path d="M245 85L234 124"/><path d="M245 85L258 124"/></g></g>,
  'sit-leg':<g>{stool}<g {...G}><circle cx="250" cy="64" r="20" fill="#e6d5bd" stroke="#b7a68e" strokeWidth="2"/><path d="M250 90L252 148"/><path d="M250 98L270 126L290 130"/><path d="M252 148L286 152L284 199"/><path d="M252 148L292 150"/><g className="v-shin"><path d="M292 150L290 199"/><path d="M290 199L304 199"/></g></g></g>,
  sit:<g>{stool}<g {...G}><g className="v-sittorso"><circle cx="250" cy="64" r="20" fill="#e6d5bd" stroke="#b7a68e" strokeWidth="2"/><path d="M250 90L252 148"/><path d="M250 98L270 126L290 130"/></g><path d="M252 148L292 150L290 199"/><path d="M252 148L286 152L284 199"/></g></g>,
  'sit-neck':<g>{stool}<g {...G}><g className="v-headsit"><circle cx="250" cy="64" r="20" fill="#e6d5bd" stroke="#b7a68e" strokeWidth="2"/></g><path d="M250 90L252 148"/><path d="M250 98L270 126L290 130"/><path d="M252 148L292 150L290 199"/><path d="M252 148L286 152L284 199"/></g></g>,
  lie:<g {...G}><ellipse cx="255" cy="208" rx="150" ry="8" fill="#d6ddc8" stroke="none"/><path d="M110 205H400" stroke="#c2cab4" strokeWidth="2"/><g className="v-breath"><circle cx="158" cy="188" r="16" fill="#e6d5bd" stroke="#b7a68e" strokeWidth="2"/><path d="M174 192L248 192"/><path d="M248 192L276 166L298 192"/><path d="M182 196L222 199"/></g></g>,
  kneel:<g {...G}><ellipse cx="255" cy="208" rx="150" ry="8" fill="#d6ddc8" stroke="none"/><path d="M110 205H400" stroke="#c2cab4" strokeWidth="2"/><circle cx="188" cy="138" r="16" fill="#e6d5bd" stroke="#b7a68e" strokeWidth="2"/><path d="M204 146L278 150"/><path d="M214 150L212 200"/><g className="v-dogA"><path d="M210 150L206 200"/></g><path d="M280 150L283 200L311 200"/><g className="v-dogB"><path d="M276 150L281 198L310 198"/></g></g>
 };
 return <div className={`exercise-demo ${playing?'moving':''}`}><svg viewBox="0 0 500 240" aria-label={`Movement illustration for ${exercise.name}`}>{v!=='lie'&&v!=='kneel'?ground:null}{figs[v]}{arrow}</svg><span><span className="live-dot"/> {exercise.type==='isometric'?`${demoLabels[v]} · breathe steadily`:demoLabels[v]}</span></div>;
}
export default function KinesioApp(){
 const [screen,setScreen]=useState<Screen>('body');const [state,setState]=useState<Recovery>(initial);const [ready,setReady]=useState(false);const [arabic,setArabic]=useState(false);const [back,setBack]=useState(false);const [sex,setSex]=useState<'male'|'female'>('male');const [zoom,setZoom]=useState(1);const [reset,setReset]=useState(0);const [allRegions,setAllRegions]=useState(false);const [query,setQuery]=useState('');const [step,setStep]=useState(0);const [rejected,setRejected]=useState<string[]>([]);const [riskAcknowledged,setRiskAcknowledged]=useState(false);const [toast,setToast]=useState('');const [sync,setSync]=useState('local');const [help,setHelp]=useState(false);const [phaseTab,setPhaseTab]=useState(1);const [exerciseIndex,setExerciseIndex]=useState(0);const [trafficOpen,setTrafficOpen]=useState(false);const [playing,setPlaying]=useState(false);const [seconds,setSeconds]=useState(30);const [sound,setSound]=useState(true);const [sessionPain,setSessionPain]=useState(3);const [feeling,setFeeling]=useState('right');const [dailyPain,setDailyPain]=useState(3);const [dailyFeeling,setDailyFeeling]=useState('same');const [sessionList,setSessionList]=useState<Exercise[]>([]);const [learnArticle,setLearnArticle]=useState<number|null>(null);const [sessionHadPain,setSessionHadPain]=useState(false);const id=useRef('');const touchStart=useRef(0);const [coarse,setCoarse]=useState(false);
 const t=(en:string,ar:string)=>arabic?ar:en;
 const update=(patch:Partial<Recovery>)=>setState(s=>({...s,...patch}));const answer=(patch:Partial<Intake>)=>setState(s=>({...s,intake:{...s.intake,...patch}}));
 useEffect(()=>{try{const saved=localStorage.getItem('kinesio-recovery');id.current=localStorage.getItem('kinesio-id')||crypto.randomUUID();localStorage.setItem('kinesio-id',id.current);if(saved){const parsed=JSON.parse(saved);setState({...initial,...parsed});if(parsed.assessed)setScreen('home');}setArabic(localStorage.getItem('kinesio-language')==='ar');}catch{id.current=crypto.randomUUID();}setReady(true);},[]);
 useEffect(()=>{if(!ready)return;localStorage.setItem('kinesio-recovery',JSON.stringify(state));const timer=setTimeout(()=>{fetch('/api/recovery',{method:'PUT',headers:{'Content-Type':'application/json'},body:JSON.stringify({id:id.current,state})}).then(r=>setSync(r.ok?'synced':'local')).catch(()=>setSync('local'));},900);return()=>clearTimeout(timer);},[state,ready]);
 useEffect(()=>{if(!toast)return;const timer=setTimeout(()=>setToast(''),5500);return()=>clearTimeout(timer);},[toast]);
 useEffect(()=>{document.documentElement.lang=arabic?'ar':'en';localStorage.setItem('kinesio-language',arabic?'ar':'en');},[arabic]);
 useEffect(()=>{const mq=window.matchMedia('(pointer:coarse)');setCoarse(mq.matches);const fn=(e:MediaQueryListEvent)=>setCoarse(e.matches);mq.addEventListener('change',fn);return()=>mq.removeEventListener('change',fn);},[]);
 useEffect(()=>{window.scrollTo({top:0});},[screen,learnArticle]);
 useEffect(()=>{if(!playing)return;const timer=setInterval(()=>setSeconds(s=>{if(s<=1){setPlaying(false);if(sound&&'speechSynthesis' in window){const cue=new SpeechSynthesisUtterance(arabic?'أحسنت، استرح قليلاً':'Well done. Take a short rest.');cue.lang=arabic?'ar':'en';speechSynthesis.speak(cue);}return 0;}return s-1;}),1000);return()=>clearInterval(timer);},[playing,sound,arabic]);
 const region=regions.find(r=>r.id===state.region);const group=region?.group||'lower-back';const matches=useMemo(()=>match(group,state.intake,rejected),[group,state.intake,rejected]);const top=matches[0];const currentPresentation=presentations.find(p=>p.id===state.presentationId)||top;const flag=redFlags(state.intake,group);const dose=doseInfo[state.intake.irritability];const plan=makeProgramme(group,state.intake,state.presentationId,phaseTab,state.goal);const progress=progression(state.logs,state.phase);const real=state.logs.length>0;const painValues=real?state.logs.map(l=>l.pain):demo.pain;const doneSessions=state.logs.filter(l=>l.session).length;const uniqueDays=[...new Set(state.logs.filter(l=>l.session).map(l=>l.date.slice(0,10)))].sort().reverse();let streak=0;for(let d=0;d<uniqueDays.length;d++){const date=new Date();date.setDate(date.getDate()-d);if(uniqueDays[d]===date.toISOString().slice(0,10))streak++;else break;}const activeExercise=sessionList[exerciseIndex];const dailyDone=state.logs.some(l=>!l.session&&l.date.slice(0,10)===new Date().toISOString().slice(0,10));
 const notify=(message:string)=>setToast(message);
 const selectRegion=(regionId:string,point?:[number,number,number])=>{const r=regions.find(r=>r.id===regionId);if(!r)return;update({region:regionId});if(point){setState(s=>({...s,region:regionId,pins:s.pins.some(p=>p.regionId===regionId)?s.pins.map(p=>p.regionId===regionId?{...p,point}:p):s.pins.length<5?[...s.pins,{id:crypto.randomUUID(),regionId,point,intensity:s.intake.pain}]:s.pins}));if(state.pins.length>=5&&!state.pins.some(p=>p.regionId===regionId))notify(t('Your map holds up to 5 points. Remove one to add another.','يمكن إضافة ٥ نقاط. احذف نقطة لإضافة أخرى.'));}else if(r.view==='back')setBack(true);};
 const beginAssessment=()=>{if(!state.region)return;setStep(0);setRejected([]);setRiskAcknowledged(false);setScreen('intake');};
 const startSession=()=>{if(!state.assessed){notify(t('Let’s understand your pain first.','لنبدأ بفهم ألمك.'));setScreen('body');return;}if(flag?.level==='urgent'){notify(t('Please get urgent medical assessment before exercising. Your plan is paused.','يرجى الحصول على تقييم طبي عاجل قبل التمرين.'));return;}setTrafficOpen(true);};
 const launchSession=()=>{const list=makeProgramme(group,state.intake,state.presentationId,state.phase,state.goal).map(e=>exercises.find(x=>x.id===state.swaps[e.id]&&!x.contraindicatedFor.includes(state.presentationId))||e);setSessionList(list);setExerciseIndex(0);setSeconds(list[0]?.holdSeconds||30);setSessionHadPain(false);setPlaying(false);setTrafficOpen(false);setScreen('session');};
 const adapt=(direction:'easier'|'harder')=>{if(!activeExercise)return;const next=variant(activeExercise,direction,state.presentationId);setSessionList(list=>list.map((e,i)=>i===exerciseIndex?next:e));update({swaps:{...state.swaps,[activeExercise.id]:next.id}});setSeconds(next.holdSeconds||30);setPlaying(false);if(direction==='easier')setSessionHadPain(true);notify(direction==='easier'?t(`Swapped to ${next.name}. We’ve reduced the load to keep this manageable.`,`تم استبدال التمرين ببديل أسهل وتقليل الحمل.`):t(`Try ${next.name}. Keep your next-morning response in mind.`,`جرّب البديل الأصعب وراقب استجابتك صباح الغد.`));};
 const nextExercise=()=>{setPlaying(false);if(exerciseIndex<sessionList.length-1){setExerciseIndex(i=>i+1);setSeconds(sessionList[exerciseIndex+1].holdSeconds||30);}else{setSessionPain(state.intake.pain);setScreen('checkin');}};
 const prevExercise=()=>{setPlaying(false);if(exerciseIndex>0){setExerciseIndex(i=>i-1);setSeconds(sessionList[exerciseIndex-1].holdSeconds||30);}};
 const finish=()=>{const log:CheckIn={date:new Date().toISOString(),pain:sessionPain,feeling:sessionHadPain?'painful':feeling,session:true,phase:state.phase};update({logs:[...state.logs,log]});notify(t('Session complete. A little consistency goes a long way.','اكتملت الجلسة. الاستمرارية تصنع الفرق.'));setScreen('home');};
 const saveDaily=()=>{const priorSession=state.logs.map(l=>l.session&&l.settled===undefined&&l.date.slice(0,10)!==new Date().toISOString().slice(0,10)&&Date.now()-new Date(l.date).getTime()<=36*60*60*1000?{...l,settled:dailyFeeling!=='worse'&&dailyPain<=l.pain,morningWorse:dailyFeeling==='worse'||dailyPain>l.pain}:l);update({logs:[...priorSession,{date:new Date().toISOString(),pain:dailyPain,feeling:dailyFeeling,session:false,phase:state.phase}]});notify(t('Check-in saved. Your next-morning response will guide your plan.','تم حفظ المتابعة وستوجّه استجابتك خطة التمارين.'));};
 const navigate=(s:Screen)=>{setPlaying(false);setScreen(s);if(s==='programme')setPhaseTab(state.phase);};
 const navs:{screen:Screen;label:string;ar:string;icon:LucideIcon}[]=[{screen:'home',label:'Overview',ar:'نظرة عامة',icon:House},{screen:'body',label:'Your body',ar:'جسمك',icon:ScanLine},{screen:'programme',label:'My programme',ar:'برنامجي',icon:Layers3},{screen:'progress',label:'My progress',ar:'تقدّمي',icon:Activity},{screen:'learn',label:'Learn & understand',ar:'تعلّم وافهم',icon:BookOpen}];
 const screenName=navs.find(n=>n.screen===screen)?.label||({intake:'Your assessment',result:'Understanding your pain',goal:'Your recovery goal',session:'Today’s session',checkin:'Session check-in'} as Record<string,string>)[screen];
 const assessmentScreens=['body','intake','result','goal'];
 const renderBody=()=> <><div className="page-heading"><div><div className="eyebrow"><span/> {t('A LITTLE UNDERSTANDING. A BETTER YOU.','فهمٌ أعمق. حركةٌ أفضل.')}</div><h1>{t('Let’s get you moving better.','لنساعدك على الحركة بشكل أفضل.')}</h1><p>{t('Every recovery starts somewhere. Let’s find your starting point.','كل رحلة تعافٍ لها بداية. لنجد نقطة بدايتك.')}</p></div><div className="time-pill"><Clock3 size={15}/>{t('About 3 minutes','حوالي ٣ دقائق')}</div></div><div className="assessment-steps">{[[t('Locate your pain','حدّد ألمك'),t('Show us where it hurts','أرنا موضع الألم')],[t('Help us understand','ساعدنا على الفهم'),t('A few questions, just for you','أسئلة قليلة تناسبك')],[t('Your personal plan','خطتك الشخصية'),t('Small steps. Real progress.','خطوات صغيرة. تقدّم حقيقي.')]].map(([title,sub],i)=><div className={i===0?'step active':'step'} key={title}><span className="step-number">0{i+1}</span><div><strong>{title}</strong><small>{sub}</small></div>{i<2&&<ChevronRight size={16}/>}</div>)}</div><div className="body-workspace"><div className="body-stage"><div className="stage-top"><span className="stage-label"><span className="live-dot"/>{t('INTERACTIVE BODY MAP','خريطة الجسم التفاعلية')}</span><button className="subtle-button" onClick={()=>setHelp(true)}><CircleHelp size={17}/>{t('How it works','كيف تعمل')}</button></div><div className="body-toggle"><button className={sex==='male'?'selected':''} onClick={()=>setSex('male')}>{t('Male','ذكر')}</button><button className={sex==='female'?'selected':''} onClick={()=>setSex('female')}>{t('Female','أنثى')}</button></div><div className="body-watermark">{t('Made to move.','خُلقت للحركة.')}</div><div className="anatomy-orbit orbit-one"/><div className="anatomy-orbit orbit-two"/><div className="body-canvas" dir="ltr"><BodyViewer active={state.region} back={back} sex={sex} zoom={zoom} reset={reset} pins={state.pins} onSelect={selectRegion}/></div><div className="orientation-label">{back?t('POSTERIOR VIEW','من الخلف'):t('ANTERIOR VIEW','من الأمام')}<span>—</span>{t('ANATOMICAL POSITION','الوضع التشريحي')}</div><div className="canvas-tools"><IconButton icon={Plus} label="Zoom in" onClick={()=>setZoom(z=>Math.min(1.8,z+.15))}/><div/><IconButton icon={Minus} label="Zoom out" onClick={()=>setZoom(z=>Math.max(.75,z-.15))}/><div/><IconButton icon={RotateCcw} label="Reset view" onClick={()=>{setZoom(1);setBack(false);setReset(r=>r+1);}}/><div/><IconButton icon={Maximize} label="Focus body" onClick={()=>setZoom(z=>z===1?1.25:1)}/></div><div className="view-switch"><button className={!back?'selected':''} onClick={()=>setBack(false)}><UserRound size={15}/>{t('Front','أمام')}</button><button className={back?'selected':''} onClick={()=>setBack(true)}><Rotate3D size={16}/>{t('Back','خلف')}</button></div><div className="rotate-hint"><Rotate3D size={15}/>{t('Drag to rotate','اسحب للتدوير')}<span>·</span>{coarse?t('Pinch to zoom','اقرص للتكبير'):t('Scroll to zoom','مرّر للتكبير')}</div></div><div className="localise-panel"><div className="panel-step"><Crosshair size={19}/><span>{t('STEP 01 · LOCATE','الخطوة ٠١ · حدّد')}</span></div><h2>{t('Where does it hurt?','أين تشعر بالألم؟')}</h2><p>{t('Tap an area on the body, or choose a region below. We’ll take it from there.','اضغط على منطقة من الجسم أو اختر منطقة أدناه. سنتابع معك من هنا.')}</p>{region?<div className="selection-card"><div className="selection-top"><span><span className="pain-dot"/>{arabic?region.labelAr:region.label}</span><IconButton icon={X} label="Clear selection" onClick={()=>update({region:'',pins:state.pins.filter(p=>p.regionId!==state.region)})}/></div><div className="selected-body-line"/><strong>{t('Is this where you feel it?','هل هذا موضع الألم؟')}</strong><p>{t('Tap the exact spot to add a pain pin. You can mark up to 5 areas.','اضغط على الموضع الدقيق لإضافة نقطة ألم. يمكنك تحديد ٥ مناطق.')}</p>{state.pins.length>0&&<div className="pin-list">{state.pins.map(p=><div key={p.id}><span>{arabic?regions.find(r=>r.id===p.regionId)?.labelAr:regions.find(r=>r.id===p.regionId)?.label}</span><input aria-label="Point pain intensity" type="range" min="0" max="10" value={p.intensity} onChange={e=>update({pins:state.pins.map(x=>x.id===p.id?{...x,intensity:+e.target.value}:x)})}/><b>{p.intensity}</b><button aria-label="Remove point" onClick={()=>update({pins:state.pins.filter(x=>x.id!==p.id)})}><X size={13}/></button></div>)}</div>}<button className="text-button" onClick={()=>{update({region:''});setAllRegions(true);}}>{t('Somewhere else','مكان آخر')}<ArrowRight size={14}/></button></div>:<><div className="section-label">{t('COMMON AREAS','مناطق شائعة')}</div><div className="region-grid">{common.map(([id,label,ar])=><button key={id} onClick={()=>selectRegion(id)}><span className="region-line-icon"><Target size={19} strokeWidth={1.3}/></span>{t(label,ar)}<ChevronRight size={13}/></button>)}</div></>}
<button className="all-regions" onClick={()=>setAllRegions(!allRegions)}>{t(allRegions?'Hide all body areas':'Explore all body areas',allRegions?'إخفاء مناطق الجسم':'استكشف جميع مناطق الجسم')}<ChevronDown size={15} className={allRegions?'rotate':''}/></button>{allRegions&&<div className="region-search"><div><Search size={16}/><input placeholder={t('Search body areas…','ابحث عن منطقة…')} value={query} onChange={e=>setQuery(e.target.value)}/></div><div className="region-results">{regions.filter(r=>(r.label+' '+r.labelAr).toLowerCase().includes(query.toLowerCase())).map(r=><button key={r.id} onClick={()=>{selectRegion(r.id);setAllRegions(false);}}>{arabic?r.labelAr:r.label}<ChevronRight size={14}/></button>)}</div></div>}<div className="localise-tip"><div className="tip-icon"><Sparkles size={18}/></div><div><strong>{t('You know your body best.','أنت الأدرى بجسمك.')}</strong><p>{t('There’s no wrong place to start. You can always adjust your selection.','لا توجد بداية خاطئة. يمكنك تعديل اختيارك في أي وقت.')}</p></div></div><div className="panel-bottom"><button className="primary-button" disabled={!state.region} onClick={beginAssessment}>{t(region?'Yes, let’s continue':'Select an area to continue',region?'نعم، لنتابع':'اختر منطقة للمتابعة')}<ArrowRight size={18}/></button><span><LockKeyhole size={12}/>{t('Your recovery. Your space.','تعافيك. مساحتك.')}</span></div></div></div><div className="trust-strip"><div><span className="trust-icon"><ShieldCheck size={20}/></span><span><strong>{t('Built around clinical reasoning','مبني على فهم سريري')}</strong><small>{t('More than a list of exercises.','أكثر من قائمة تمارين.')}</small></span></div><div><span className="trust-icon"><Settings2 size={20}/></span><span><strong>{t('A plan that adapts to you','خطة تتكيّف معك')}</strong><small>{t('Your progress sets the pace.','تقدّمك يحدّد الإيقاع.')}</small></span></div><div><span className="trust-icon"><Heart size={20}/></span><span><strong>{t('Small steps, lasting change','خطوات صغيرة، تغيير مستدام')}</strong><small>{t('Designed for your everyday.','مصمّمة لحياتك اليومية.')}</small></span></div></div></>;
 const questionTitles=[t('How does it feel right now?','كيف تشعر الآن؟'),t('How did your pain begin?','كيف بدأ الألم؟'),t('How long has this been going on?','منذ متى تشعر بهذا الألم؟'),t('When do you notice it most?','متى تلاحظ الألم أكثر؟'),t('Which movements change your pain?','ما الحركات التي تغيّر ألمك؟'),t('How easily is your pain stirred up?','ما مدى سهولة إثارة الألم؟'),t('Any tingling, numbness or weakness?','هل هناك وخز أو خدر أو ضعف؟')];
 const chip=(value:string,label:string,selected:boolean,action:()=>void)=><button key={value} className={`choice-chip ${selected?'chosen':''}`} onClick={action}>{label}{selected&&<Check size={15}/>}</button>;
 const toggleDetail=(key:string)=>answer({details:state.intake.details.includes(key)?state.intake.details.filter(d=>d!==key):[...state.intake.details,key]});
 const renderIntake=()=> <div className="assessment-page"><button className="back-link" onClick={()=>step?setStep(step-1):setScreen('body')}><ArrowLeft size={16}/>{t('Back','رجوع')}</button><div className="assessment-layout"><div className="intake-card"><div className="eyebrow">{t('HELP US UNDERSTAND','ساعدنا على الفهم')}<span className="question-count">0{step+1} / 07</span></div><div className="question-progress"><i style={{width:`${(step+1)/7*100}%`}}/></div><h1>{questionTitles[step]}</h1><p>{step===5?t('This helps us find the right dose — not just the right exercises.','يساعدنا هذا في تحديد الجرعة المناسبة، وليس التمارين فقط.'):t(`A few details about your ${region?.label.toLowerCase()||'pain'} will help make your plan feel like yours.`,`تفاصيل قليلة عن ألمك تساعدنا في تخصيص خطتك.`)}</p><div className="question-body">{step===0&&(['pain','worst','best'] as const).map((key,i)=><div className="pain-slider" key={key}><label>{[t('Right now','الآن'),t('At its worst','في أسوأ حالاته'),t('At its best','في أفضل حالاته')][i]}<b>{state.intake[key]}<small>/10</small></b></label><input aria-label={key} type="range" min="0" max="10" value={state.intake[key]} onChange={e=>{const n=+e.target.value;if(key==='pain')answer({pain:n,best:Math.min(state.intake.best,n),worst:Math.max(state.intake.worst,n)});else answer({[key]:key==='best'?Math.min(n,state.intake.pain):Math.max(n,state.intake.pain)});}}/><div className="slider-labels"><span>{t('No pain','لا ألم')}</span><span>{t('Worst imaginable','أشد ألم ممكن')}</span></div></div>)}{step===1&&<><div className="option-stack">{[['incident',t('Suddenly, after an incident','فجأة بعد حادث'),t('A twist, fall, lift or specific moment.','التواء أو سقوط أو رفع أو لحظة محددة.')],['gradual',t('It crept up over time','تدريجياً مع الوقت'),t('No single moment — it gradually appeared.','لا توجد لحظة محددة، ظهر تدريجياً.')]].map(([v,label,sub])=><button key={v} className={state.intake.onset===v?'option selected':'option'} onClick={()=>answer({onset:v,details:state.intake.details.filter(d=>d!=='major-trauma')})}><span className="radio-dot"/><span><strong>{label}</strong><small>{sub}</small></span></button>)}</div>{state.intake.onset==='incident'&&<div className="detail-chips"><span>{t('Was it a significant fall or collision?','هل كان سقوطاً أو اصطداماً كبيراً؟')}</span>{chip('major-trauma',t('Yes, a major impact','نعم، إصابة شديدة'),state.intake.details.includes('major-trauma'),()=>toggleDetail('major-trauma'))}</div>}</>}{step===2&&<div className="option-stack">{[['acute',t('Less than 6 weeks','أقل من ٦ أسابيع'),t('A fairly recent change','تغيّر حديث نسبياً')],['subacute',t('6–12 weeks','٦–١٢ أسبوعاً'),t('It’s been a little while','مستمر منذ فترة')],['persistent',t('More than 12 weeks','أكثر من ١٢ أسبوعاً'),t('I’ve been living with this','أتعايش معه منذ مدة')]].map(([v,label,sub])=><button key={v} className={`option ${state.intake.duration===v?'selected':''}`} onClick={()=>answer({duration:v})}><span className="radio-dot"/><span><strong>{label}</strong><small>{sub}</small></span></button>)}</div>}{step===3&&<><div className="option-stack">{[['morning',t('In the morning, then it eases','في الصباح ثم يخف'),t('Moving around helps loosen things up.','تساعد الحركة على تخفيف التيبس.')],['load',t('With activity or later in the day','مع النشاط أو نهاية اليوم'),t('It builds up as I do more.','يزداد مع زيادة النشاط.')],['night',t('At night — it wakes me up','ليلاً ويوقظني'),t('Not just when I roll onto it.','ليس فقط عند النوم على المنطقة.')]].map(([v,label,sub])=><button key={v} className={`option ${state.intake.pattern===v?'selected':''}`} onClick={()=>answer({pattern:v})}><span className="radio-dot"/><span><strong>{label}</strong><small>{sub}</small></span></button>)}</div>{state.intake.pattern==='night'&&<div className="detail-chips"><span>{t('Anything else alongside this? Select only if present.','هل يصاحب ذلك شيء آخر؟ اختر إن وجد.')}</span>{[['fever',t('Fever or feeling unwell','حمى أو شعور بالمرض')],['weight-loss',t('Unexplained weight loss','نقص وزن غير مبرر')]].map(([v,l])=>chip(v,l,state.intake.details.includes(v),()=>toggleDetail(v)))}</div>}</>}{step===4&&<><div className="section-label">{t('MAKES IT WORSE · CHOOSE ANY','يزيد الألم · اختر ما ينطبق')}</div><div className="chips">{aggravators[group].map(([v,l])=>chip(v,arabic?arabicChips[v]:l,state.intake.aggravators.includes(v),()=>answer({aggravators:state.intake.aggravators.includes(v)?state.intake.aggravators.filter(x=>x!==v):[...state.intake.aggravators,v],easers:state.intake.easers.filter(x=>x!==v)})))}</div><div className="section-label space-top">{t('HELPS IT EASE','يساعد على تخفيفه')}</div><div className="chips">{[...aggravators[group].filter(([v])=>!state.intake.aggravators.includes(v)),['rest','Resting']].map(([v,l])=>chip(v,arabic?arabicChips[v]||'الراحة':l,state.intake.easers.includes(v),()=>answer({easers:state.intake.easers.includes(v)?state.intake.easers.filter(x=>x!==v):[...state.intake.easers,v]})))}</div></>}{step===5&&<div className="option-stack">{[['high',t('Very little sets it off','نشاط بسيط يثير الألم'),t('It lingers for hours afterwards.','يستمر الألم لساعات بعد ذلك.')],['moderate',t('A moderate amount of activity','كمية معتدلة من النشاط'),t('It settles within about an hour.','يهدأ خلال ساعة تقريباً.')],['low',t('It takes quite a lot','يحتاج إلى نشاط كثير'),t('It settles again within minutes.','يهدأ مجدداً خلال دقائق.')]].map(([v,label,sub])=><button key={v} className={`option ${state.intake.irritability===v?'selected':''}`} onClick={()=>answer({irritability:v as Intake['irritability']})}><span className="radio-dot"/><span><strong>{label}</strong><small>{sub}</small></span></button>)}</div>}{step===6&&<><div className="chips">{[['none',t('No, none of these','لا شيء من ذلك')],['tingling',t('Yes, tingling or numbness','نعم، وخز أو خدر')],['weakness',t('Yes, weakness','نعم، ضعف')]].map(([v,l])=>chip(v,l,state.intake.neuro===v,()=>answer({neuro:v,details:state.intake.details.filter(d=>!['weakness','arm','leg','both-legs','saddle','bladder'].includes(d))})))}</div>{state.intake.neuro!=='none'&&<div className="detail-chips"><span>{t('Where does it travel, or what have you noticed?','إلى أين يمتد أو ماذا لاحظت؟')}</span>{(group==='lower-back'||group==='hip'?[['leg',t('Into one leg','إلى ساق واحدة')],['both-legs',t('Into both legs','إلى الساقين')],['saddle',t('Numb around my seat / groin','خدر حول المقعد أو الأربية')],['bladder',t('New bladder or bowel changes','تغيّرات جديدة في المثانة أو الأمعاء')]]:[['arm',t('Into my arm or hand','إلى الذراع أو اليد')]]).concat([['weakness',t('Weakness is getting worse','الضعف يزداد')]]).map(([v,l])=>chip(v,l,state.intake.details.includes(v),()=>toggleDetail(v)))}</div>}{['neck','shoulder','upper-back'].includes(group)&&<div className="detail-chips"><span>{t('Any associated symptoms?','هل توجد أعراض مصاحبة؟')}</span>{chip('chest',t('Chest pain / breathlessness','ألم صدر أو ضيق تنفس'),state.intake.details.includes('chest'),()=>toggleDetail('chest'))}{group==='neck'&&chip('severe-headache',t('First sudden, severe headache','أول صداع مفاجئ وشديد'),state.intake.details.includes('severe-headache'),()=>toggleDetail('severe-headache'))}</div>}</>}</div><div className="intake-footer"><span><ShieldCheck size={15}/>{t('Your answers shape your plan.','إجاباتك تشكّل خطتك.')}</span><button className="primary-button" onClick={()=>{if(step<6)setStep(step+1);else setScreen('result');}}>{step===6?t('Understand my pain','افهم ألمي'):t('Continue','متابعة')}<ArrowRight size={17}/></button></div></div><aside className="intake-aside"><div className="mini-body" dir="ltr"><BodyViewer active={state.region} back={region?.view==='back'} pins={state.pins} mini/></div><span className="badge"><Crosshair size={13}/>{arabic?region?.labelAr:region?.label}</span><h3>{t('A person, not a body part.','أنت إنسان، لا مجرد منطقة ألم.')}</h3><p>{t('Your symptoms, your day, your goals. They all help us choose what’s right for you.','أعراضك ويومك وأهدافك، كلها تساعدنا على اختيار ما يناسبك.')}</p></aside></div></div>;
 const renderResult=()=> <div className="center-flow"><div className="eyebrow"><Sparkles size={16}/>{t('CONNECTING THE DOTS','ربط التفاصيل')}</div>{flag&&!riskAcknowledged?<div className="result-card"><span className="risk-symbol"><Heart size={27}/></span><h1>{t('Let’s get a little more support.','لنحصل على دعم إضافي.')}</h1><p>{t('A few of your answers are worth getting checked in person before starting exercises.','بعض إجاباتك تستحق تقييماً شخصياً قبل بدء التمارين.')}</p><div className="notice amber">{arabic?(flag.level==='urgent'?'اطلب تقييماً طبياً عاجلاً الآن. لا تبدأ التمارين.':'احجز تقييماً شخصياً قبل بدء التمارين.'):flag.message}</div><button className="primary-button" onClick={()=>{setRiskAcknowledged(true);notify(t('You can explore the explanation. Urgent symptoms keep sessions paused.','يمكنك قراءة الشرح. الأعراض العاجلة توقف الجلسات.'));}}>{t('Continue anyway','المتابعة على أي حال')}<ArrowRight size={16}/></button><button className="text-button" onClick={()=>{setStep(6);setScreen('intake');}}>{t('Review my answers','مراجعة إجاباتي')}</button></div>:<><h1>{t('This looks most like…','يبدو هذا أقرب إلى…')}</h1><p className="flow-subtitle">{t('A useful starting point, not a definitive diagnosis.','نقطة بداية مفيدة، وليست تشخيصاً نهائياً.')}</p><div className="result-card"><span className="badge"><span className="live-dot"/>{t(top.confidence,'تطابق محتمل للنمط')}</span><h2>{arabic?top.nameAr:top.name}</h2><p>{arabic?'يمكن للحركة المريحة والحمل التدريجي أن يساعدا في بناء القدرة. استجابتك هي التي توجّه التقدّم.':top.explanation}</p><div className="result-facts"><div><Clock3 size={20}/><strong>{t('What to expect','ما يمكن توقعه')}</strong><p>{arabic?'غالباً يتحسن تدريجياً مع روتين منتظم ويمكن للأعراض المزمنة أن تتحسن أيضاً.':top.course}</p></div><div><Footprints size={20}/><strong>{t('What actually helps','ما يساعد فعلاً')}</strong><p>{arabic?'ابدأ بجرعة يمكنك التعافي منها، وراقب استجابة صباح اليوم التالي.':top.helps}</p></div></div><details><summary>{t('Why this pattern?','لماذا هذا النمط؟')}</summary><p>{t(`We matched your ${state.intake.onset} onset, ${state.intake.pattern} pattern, ${state.intake.aggravators.length} movement triggers and nerve symptoms. Rule score: ${top.score}. Scores describe fit, not diagnostic certainty.`,`قارنا بداية الألم ونمطه والحركات المؤثرة وأعراض الأعصاب. الدرجة تعبّر عن التطابق وليس اليقين التشخيصي.`)}</p></details><button className="text-button" onClick={()=>{if(rejected.length>=matches.length-1){setRejected([]);setStep(4);setScreen('intake');}else setRejected([...rejected,top.id]);}}>{t('That doesn’t sound like me','هذا لا يشبه ما أشعر به')}<RotateCcw size={14}/></button></div><div className="could-be"><span>{t('COULD ALSO BE','قد يكون أيضاً')}</span><strong>{arabic?matches[1]?.nameAr:matches[1]?.name}</strong><p>{arabic?'هناك تداخل بين الأنماط. سنراقب استجابتك ونتكيّف معها.':matches[1]?.explanation}</p></div><button className="primary-button wide" onClick={()=>{update({presentationId:top.id});setScreen('goal');}}>{t('Let’s build my plan','لنُنشئ خطتي')}<ArrowRight size={18}/></button></>}</div>;
 const renderGoal=()=> <div className="center-flow"><span className="round-feature"><FlagIcon/></span><div className="eyebrow">{t('YOUR REASON TO MOVE','سببك للحركة')}</div><h1>{t('What do you want to get back to?','إلى ماذا تريد العودة؟')}</h1><p className="flow-subtitle">{t('Recovery means more when it’s about something you love.','للتعافي معنى أكبر عندما يرتبط بشيء تحبه.')}</p><div className="goal-grid">{[[Footprints,'Walk and move comfortably','المشي والحركة براحة'],[Dumbbell,'Get back to training','العودة إلى التدريب'],[Heart,'Keep up with my family','مواكبة عائلتي'],[House,'Feel better at work','الشعور براحة في العمل']].map(([I,en,ar])=>{const Icon=I as LucideIcon;return <button key={en as string} className={state.goal===en?'goal-card selected':'goal-card'} onClick={()=>update({goal:en as string})}><Icon size={27}/><span>{t(en as string,ar as string)}</span>{state.goal===en&&<Check size={17}/>}</button>;})}</div><label className="custom-goal">{t('Or, in your own words','أو بكلماتك')}<input value={state.goal} maxLength={160} onChange={e=>update({goal:e.target.value})} placeholder={t('I want to…','أريد أن…')}/></label><div className="notice"><Sparkles size={20}/><span>{t(`${dose.character}. About ${dose.minutes} minutes, ${dose.frequency.toLowerCase()}. That’s where we’ll start.`,`سنبدأ بحركة تناسب استجابتك، حوالي ${dose.minutes} دقيقة لكل جلسة.`)}</span></div><button className="primary-button wide" disabled={!state.goal.trim()} onClick={()=>{update({assessed:true,phase:1});setPhaseTab(1);setScreen('programme');notify(t('Your plan is ready. Built around your answers, at your pace.','خطتك جاهزة ومبنية على إجاباتك وبإيقاع يناسبك.'));}}>{t('See my personal programme','عرض برنامجي الشخصي')}<ArrowRight size={18}/></button></div>;
 const renderProgramme=()=> <><div className="page-heading"><div><div className="eyebrow">{t('YOUR WAY FORWARD','طريقك إلى الأمام')}</div><h1>{t('Small steps. Stronger you.','خطوات صغيرة. أنت أقوى.')}</h1><p>{state.assessed?t(`Your goal: ${state.goal}`,'هدفك هو العودة إلى ما تحب.'):t('Explore a sample programme, then build one around you.','استكشف نموذج برنامج ثم أنشئ برنامجك.')}</p></div><span className="badge"><Settings2 size={14}/>{t(`${state.intake.irritability} irritability`,'جرعة مخصّصة')}</span></div>{!state.assessed&&<div className="sample-banner"><Sparkles size={17}/>{t('Sample programme · Complete your body assessment for your own plan.','نموذج برنامج · أكمل تقييمك للحصول على خطتك.')}<button onClick={()=>setScreen('body')}>{t('Get my plan','إنشاء خطتي')}<ArrowRight size={15}/></button></div>}<div className="phase-grid">{[[1,'Calm','Find comfortable movement','Typically days 1–14'],[2,'Load','Rebuild strength & control','Typically weeks 2–6'],[3,'Capacity','Get back to what you love','Typically weeks 6–12']].map(([n,name,sub,time])=><button key={n} className={`phase-card ${phaseTab===n?'selected':''}`} onClick={()=>setPhaseTab(n as number)}><div><span className="phase-index">0{n}</span>{Number(n)>state.phase?<LockKeyhole size={17}/>:<Check size={17}/>}</div><h2>{t(name as string,n===1?'تهدئة':n===2?'تحميل':'قدرة')}</h2><p>{t(sub as string,n===1?'العثور على حركة مريحة':n===2?'بناء القوة والتحكّم':'العودة لما تحب')}</p><small>{t(time as string,'التقدّم حسب استجابتك، لا التقويم')}</small><span className="phase-status">{n===state.phase?t('YOUR CURRENT PHASE','مرحلتك الحالية'):Number(n)>state.phase?t('EARNED, NOT SCHEDULED','تُكتسب ولا تُجدول'):t('COMPLETED','مكتملة')}</span></button>)}</div><div className="programme-layout"><section><div className="section-heading"><h2>{t(phaseTab===state.phase?'Your next session':'What’s ahead',phaseTab===state.phase?'جلستك التالية':'ما ينتظرك')}</h2><span><Clock3 size={15}/>{dose.minutes} {t('min','دقيقة')}<span>·</span>{plan.length} {t('exercises','تمارين')}</span></div><div className="exercise-list">{plan.map((e,i)=><div className="exercise-row" key={e.id}><span className="exercise-order">0{i+1}</span><div className="exercise-type-icon">{e.type==='mobility'?<Rotate3D size={25}/>:<Dumbbell size={25}/>}</div><div className="exercise-info"><h3>{arabic?e.nameAr:e.name}</h3><p>{e.sets} {t('sets','مجموعات')} × {e.holdSeconds?`${e.holdSeconds}s ${t('hold','ثبات')}`:`${e.reps} ${t('reps','تكرارات')}`}<span>·</span>{arabic?'ببطء وتحكّم':e.tempo}</p><details><summary>{t('Why this exercise?','لماذا هذا التمرين؟')}</summary><p>{t(`${e.type==='mobility'?'Keeps useful movement comfortable':e.type==='isometric'?'Introduces load without a large movement':'Builds tolerance for everyday load'} for ${currentPresentation.name.toLowerCase()}. ${e.cues[1]}`,'يساعد هذا التمرين على بناء القدرة والحفاظ على الحركة المريحة تدريجياً.')}</p></details></div><span className="exercise-equipment">{e.equipment==='none'?t('No equipment','دون أدوات'):e.equipment}</span></div>)}</div><div className="notice"><Sparkles size={19}/><span>{t(state.intake.irritability==='high'?'Your pain is easily stirred up, so we’ve kept the range small and the session short. Gentle doses first — we’ll build from here.':state.intake.duration==='persistent'?'You’ve been dealing with this for a while. We’ll build confidence and capacity with manageable loading — your body is adaptable.':'Your response matters more than the calendar. We’ll add load when your pain is steady and the current exercises feel manageable.','استجابتك أهم من التقويم. نزيد الحمل عندما يستقر الألم وتصبح التمارين مناسبة.')}</span></div></section><aside className="programme-aside"><span className="eyebrow">{t('MADE FOR YOUR EVERYDAY','مصمّم ليومك')}</span><h3>{t('A little, consistently.','القليل، باستمرار.')}</h3><p>{t(dose.frequency,'وتيرة تتناسب مع استجابتك')}</p><div className="programme-stat"><Clock3 size={20}/><div><strong>{dose.minutes} {t('minutes','دقيقة')}</strong><small>{t('You can make time for you.','وقت صغير من أجلك.')}</small></div></div><div className="programme-stat"><Target size={20}/><div><strong>{t('Progress at your pace','تقدّم بإيقاعك')}</strong><small>{t('70% adherence + stable pain + manageable effort + next-day recovery.','التزام ٧٠٪ وألم مستقر وجهد مناسب وتعافٍ في اليوم التالي.')}</small></div></div><button className="primary-button" onClick={startSession}>{t('Start my session','ابدأ جلستي')}<Play size={16}/></button><a className="text-button" href="/handout" style={{marginTop:12}}><Printer size={15}/>{t('Print my programme','طباعة برنامجي')}</a><span className="muted-note">{t('A small step in the right direction.','خطوة صغيرة في الاتجاه الصحيح.')}</span></aside></div></>;
 const renderHome=()=> <><div className="page-heading"><div><div className="eyebrow"><span/>{t('YOUR DAILY DOSE OF BETTER','جرعتك اليومية للتحسّن')}</div><h1>{t('A little movement. A good day.','قليل من الحركة. يوم أفضل.')}</h1><p>{t('No catching up. No falling behind. Just your next small step.','لا تأخّر ولا سباق. فقط خطوتك الصغيرة التالية.')}</p></div><span className="badge"><Flame size={15}/>{streak} {t('day streak','أيام متتالية')}</span></div>{!state.assessed?<div className="home-session"><div><span className="eyebrow">{t('YOUR RECOVERY STARTS HERE','تعافيك يبدأ هنا')}</span><h2>{t('A plan that starts with you.','خطة تبدأ بك.')}</h2><p>{t('Show us where it hurts. Answer a few questions. Find a manageable way forward.','حدّد الألم وأجب عن أسئلة قليلة، ثم ابدأ طريقك المناسب.')}</p><button className="primary-button" onClick={()=>setScreen('body')}>{t('Find my starting point','ابحث عن نقطة بدايتي')}<ArrowRight size={18}/></button></div><div className="home-art"><ScanLine size={120} strokeWidth={.6}/></div></div>:<div className="home-session"><div><span className="badge">{t(`PHASE ${state.phase} · ${['CALM','LOAD','CAPACITY'][state.phase-1]}`,'مرحلتك الحالية')}</span><h2>{t('Your next step is a small one.','خطوتك التالية صغيرة.')}</h2><p>{t(`${dose.minutes} minutes of ${dose.character.toLowerCase()}, chosen for your ${region?.label.toLowerCase()}.`,`جلسة من ${dose.minutes} دقيقة صُممت خصيصاً لك.`)}</p><div className="session-meta"><span><Clock3 size={16}/>{dose.minutes} {t('min','دقيقة')}</span><span><Dumbbell size={16}/>{t('4 exercises','٤ تمارين')}</span><span><Heart size={16}/>{t('At your pace','بإيقاعك')}</span></div><button className="primary-button" onClick={startSession}><Play size={17}/>{t('Start today’s session','ابدأ جلسة اليوم')}<ArrowRight size={18}/></button></div><div className="home-body" dir="ltr"><BodyViewer active={state.region} back={region?.view==='back'} mini/></div></div>}<div className="home-grid"><div className="dashboard-card"><div className="section-heading"><h3>{t('How’s the pain today?','كيف الألم اليوم؟')}</h3><span className="eyebrow">{t('A QUICK CHECK-IN','متابعة سريعة')}</span></div>{dailyDone?<div className="checkin-done"><Check size={25}/><h3>{t('You’ve checked in today.','سجّلت متابعتك اليوم.')}</h3><p>{t('Thank you for listening to your body.','شكراً لإنصاتك لجسمك.')}</p></div>:<><div className="daily-pain-number">{dailyPain}<span>/ 10</span></div><input aria-label="Pain today" type="range" min="0" max="10" value={dailyPain} onChange={e=>setDailyPain(+e.target.value)}/><div className="slider-labels"><span>{t('No pain','لا ألم')}</span><span>{t('Worst imaginable','أشد ألم ممكن')}</span></div><p className="checkin-question">{t('Compared with before your last session?','مقارنة بما قبل جلستك السابقة؟')}</p><div className="chips">{[['better',t('Better','أفضل')],['same',t('About the same','نفسه تقريباً')],['worse',t('Worse','أسوأ')]].map(([v,l])=>chip(v,l,dailyFeeling===v,()=>setDailyFeeling(v)))}</div><button className="text-button" onClick={saveDaily}>{t('Save my check-in','حفظ متابعتي')}<ArrowRight size={16}/></button></>}</div><div className="dashboard-card"><div className="section-heading"><h3>{t('Your bigger picture','صورتك الأكبر')}</h3><TrendingDown size={19}/></div>{!real&&<span className="sample-label">{t('SAMPLE JOURNEY','رحلة نموذجية')}</span>}<div className="trend-summary"><strong>{painValues.at(-1)}<span>/ 10</span></strong><span>{t('Latest pain score','أحدث مستوى ألم')}</span></div><Sparkline values={painValues}/><button className="text-button" onClick={()=>setScreen('progress')}>{t('See my progress','عرض تقدّمي')}<ArrowRight size={16}/></button></div></div><div className="education-banner"><BookOpen size={27}/><div><strong>{t('Your body is stronger than you think.','جسمك أقوى مما تظن.')}</strong><p>{t('A little understanding can change the way you move.','القليل من الفهم قد يغيّر طريقة حركتك.')}</p></div><button onClick={()=>{setLearnArticle(0);setScreen('learn');}}>{t('Take a minute to learn','دقيقة للتعلّم')}<ArrowUpRight size={16}/></button></div></>;
 const renderSession=()=>activeExercise?<div className="session-page"><div className="section-heading"><button className="back-link" onClick={()=>{setPlaying(false);setScreen('home');}}><X size={17}/>{t('Finish later','أكمل لاحقاً')}</button><span>{t('EXERCISE','تمرين')} 0{exerciseIndex+1} / 0{sessionList.length}</span><IconButton icon={sound?Volume2:VolumeX} label="Toggle audio cues" onClick={()=>setSound(!sound)}/></div><div className="session-progress">{sessionList.map((e,i)=><i key={e.id+i} className={i<=exerciseIndex?'complete':''}/>)}</div><div className="session-player" onTouchStart={e=>{touchStart.current=e.touches[0].clientX;}} onTouchEnd={e=>{const d=touchStart.current-e.changedTouches[0].clientX;if(d>70)nextExercise();else if(d<-70)prevExercise();}}><div className="session-visual"><ExerciseDemo exercise={activeExercise} playing={playing}/><div className="target-mini"><div dir="ltr"><BodyViewer active={activeExercise.targetRegions[0]} back={group==='lower-back'||group==='upper-back'} mini/></div><span>{t('YOUR TARGET AREA','المنطقة المستهدفة')}</span></div><span className="illustration-note">{t('Movement illustration · Follow the cues for your exercise','رسم توضيحي للحركة · اتبع إرشادات تمرينك')}</span></div><div className="session-instructions"><span className="eyebrow">{t(activeExercise.type.replace('_',' '),'حركة موجّهة')}</span><h1>{arabic?activeExercise.nameAr:activeExercise.name}</h1><div className="dose-box"><div><strong>{activeExercise.sets}</strong><span>{t('SETS','مجموعات')}</span></div><span>×</span><div><strong>{activeExercise.holdSeconds||activeExercise.reps}<small>{activeExercise.holdSeconds?'s':''}</small></strong><span>{activeExercise.holdSeconds?t('HOLD','ثبات'):t('REPS','تكرارات')}</span></div><div><Clock3 size={20}/><span>{arabic?'ببطء وتحكّم':activeExercise.tempo}</span></div></div><ol className="cue-list">{activeExercise.cues.slice(0,3).map((c,i)=><li key={c}><span>{i+1}</span>{arabic?['ابدأ من وضع مريح.','تحرّك ببطء ضمن نطاق مناسب.','واصل التنفس ولا تحبس أنفاسك.'][i]:c}</li>)}</ol><div className="timer"><span>{Math.floor(seconds/60).toString().padStart(2,'0')}:{(seconds%60).toString().padStart(2,'0')}</span><button aria-label={playing?'Pause timer':'Start timer'} onClick={()=>{if(seconds===0)setSeconds(activeExercise.holdSeconds||30);setPlaying(!playing);}}>{playing?<Pause size={23}/>:<Play size={23}/>}</button><IconButton icon={RotateCcw} label="Reset timer" onClick={()=>{setSeconds(activeExercise.holdSeconds||30);setPlaying(false);}}/></div><div className="adapt-buttons"><button onClick={()=>adapt('easier')}><ArrowDown size={16}/>{t('Too painful','مؤلم جداً')}</button><button onClick={()=>adapt('harder')}>{t('Too easy','سهل جداً')}<ArrowUpRight size={16}/></button></div><button className="primary-button" onClick={nextExercise}>{exerciseIndex===sessionList.length-1?t('Finish & check in','إنهاء ومتابعة'):t('Next exercise','التمرين التالي')}<ArrowRight size={17}/></button><span className="muted-note">{t('Keep it ≤ 4/10. It should settle within 24 hours.','أبقِ الألم ≤ ٤/١٠ ويجب أن يهدأ خلال ٢٤ ساعة.')}{coarse&&<> · {t('Swipe for next / previous','اسحب للتنقل بين التمارين')}</>}</span></div></div></div>:null;
 const renderCheckin=()=> <div className="center-flow checkin-flow"><span className="round-feature"><Check size={30}/></span><span className="eyebrow">{t('YOU SHOWED UP FOR YOURSELF','لقد اعتنيت بنفسك')}</span><h1>{t('That’s a step forward.','هذه خطوة إلى الأمام.')}</h1><p>{t('One quick check-in helps us make your next session better.','متابعة سريعة تساعدنا على تحسين جلستك التالية.')}</p><div className="result-card"><div className="pain-slider"><label>{t('Highest pain during your session?','أعلى ألم أثناء الجلسة؟')}<b>{sessionPain}<small>/10</small></b></label><input aria-label="Pain during session" type="range" min="0" max="10" value={sessionPain} onChange={e=>setSessionPain(+e.target.value)}/><div className="slider-labels"><span>{t('No pain','لا ألم')}</span><span>{t('Worst imaginable','أشد ألم ممكن')}</span></div></div><h3>{t('How did the exercises feel?','كيف كانت التمارين؟')}</h3><div className="chips">{[['easy',t('Easy','سهلة')],['right',t('Just right','مناسبة')],['hard',t('Too challenging','صعبة جداً')]].map(([v,l])=>chip(v,l,feeling===v,()=>setFeeling(v)))}</div><div className={`notice ${sessionPain>4?'amber':''}`}>{t(sessionPain>4?'That was above your comfortable zone. We’ll keep your next session gentle. Check how you feel tomorrow morning.':'Good work. The last part of the traffic light is tomorrow: symptoms should settle within 24 hours and not be worse in the morning.','راقب استجابتك غداً: يجب أن يهدأ الألم خلال ٢٤ ساعة وألا يكون أسوأ صباحاً.')}</div><button className="primary-button wide" onClick={()=>{if(sessionPain>4||feeling==='hard')answer({irritability:'high'});finish();}}>{t('Save & finish','حفظ وإنهاء')}<Check size={17}/></button></div></div>;
 const renderProgress=()=> <><div className="page-heading"><div><div className="eyebrow">{t('THE BIGGER PICTURE','الصورة الأكبر')}</div><h1>{t('Progress isn’t always a straight line.','التقدّم ليس دائماً خطاً مستقيماً.')}</h1><p>{t('Look at how far you’ve come, not just how today feels.','انظر إلى المسافة التي قطعتها، لا إلى شعور اليوم فقط.')}</p></div><span className="badge"><Activity size={15}/>{t('Weekly review','المراجعة الأسبوعية')}</span></div>{!real&&<div className="sample-banner"><Sparkles size={17}/>{t('Sample recovery journey · Your own check-ins will replace this example.','رحلة تعافٍ نموذجية · ستحل بياناتك محل هذا المثال.')}</div>}<div className="progress-stat-grid"><div className="dashboard-card"><span>{t('LATEST PAIN','أحدث مستوى ألم')}</span><strong>{painValues.at(-1)}<small> / 10</small></strong><p><TrendingDown size={16}/>{t(`Started at ${painValues[0]}/10`,`بدأ عند ${painValues[0]}/١٠`)}</p></div><div className="dashboard-card"><span>{t('SESSIONS COMPLETED','الجلسات المكتملة')}</span><strong>{real?doneSessions:demo.sessions}<small> / {real?10:demo.planned}</small></strong><p><Check size={16}/>{t('Every session counts.','كل جلسة مهمة.')}</p></div><div className="dashboard-card"><span>{t('PHASE CONSISTENCY','الالتزام في المرحلة')}</span><strong>{real?progress.adherence:80}<small>%</small></strong><p><Flame size={16}/>{t('70% unlocks the next check.','٧٠٪ تسمح بفحص شروط التقدّم.')}</p></div></div><div className="progress-main"><div className="dashboard-card"><div className="section-heading"><h3>{t('A little better, over time','أفضل قليلاً مع الوقت')}</h3><span className="chart-key"><i/>{t('Pain score','درجة الألم')}</span></div><Sparkline values={painValues} large/><div className="chart-dates"><span>{t('Your starting point','نقطة البداية')}</span><span>{t('Today','اليوم')}</span></div></div><div className="dashboard-card pain-map-card"><div className="section-heading"><h3>{t('Your pain map','خريطة ألمك')}</h3><span className="badge">{painValues.at(-1)}/10</span></div><div dir="ltr"><BodyViewer active={(painValues.at(-1)||0)>2?(state.region||'lower-back'):''} back={true} pins={state.pins.map(p=>({...p,intensity:painValues.at(-1)||0}))} mini/></div><span>{t('Less pain. More possibility.','ألم أقل. إمكانيات أكثر.')}</span></div></div><div className="review-card"><div className="review-icon"><Sparkles size={25}/></div><div><span className="eyebrow">{t('YOUR NEXT CHAPTER','فصلك التالي')}</span><h2>{t(real?(progress.action==='advance'?'You’ve earned a little more.':progress.action==='regress'?'Let’s make a little more room for recovery.':'Let’s keep building a steady foundation.'):'Consistency is making a difference.','لنواصل بناء أساس ثابت.')}</h2><p>{t(real?progress.action==='advance'?`You’ve completed ${progress.adherence}% of sessions, pain is steady or falling, and the last session felt manageable with next-day recovery. You’re ready for the next phase.`:progress.action==='regress'?'Your recent pain trend is rising. We’ll reduce the dose. An in-person assessment can help us understand what’s changed.':`You’ve completed ${doneSessions} sessions. We’ll hold this phase until at least 7 of 10 are complete, pain is steady, exercises feel right, and your next-morning response is good.`:'In this sample journey, pain dropped from 6 to 2 with 8 of 10 sessions complete. Your own reviews will explain exactly when and why your programme changes.','يرتبط التقدّم بالالتزام واستقرار الألم وسهولة التمارين والتعافي في اليوم التالي.')}</p>{real&&progress.action==='advance'&&state.phase<3&&<button className="primary-button" onClick={()=>{update({phase:state.phase+1,intake:{...state.intake,irritability:'moderate'}});setPhaseTab(state.phase+1);setScreen('programme');notify(t('Phase unlocked. Your next session now includes more controlled loading.','تم فتح المرحلة التالية وزيادة الحمل المتحكّم به.'));}}>{t('Move to the next phase','انتقل للمرحلة التالية')}<ArrowRight size={17}/></button>}{real&&progress.action==='regress'&&<button className="text-button" onClick={()=>{answer({irritability:'high'});update({phase:Math.max(1,state.phase-1)});notify(t('Your dose is reduced to short, gentle sessions.','تم تقليل الجرعة إلى جلسات قصيرة ولطيفة.'));}}>{t('Reduce my dose','تقليل جرعتي')}<ArrowDown size={16}/></button>}</div></div>{real&&((state.logs.length&&new Date().getTime()-new Date(state.logs[0].date).getTime()>28*86400000&&progress.trend>=0)||progress.trend>1)&&<div className="notice amber"><Heart size={20}/>{t('You haven’t been improving as expected. An in-person physiotherapy assessment is a good next step.','التحسّن ليس كما هو متوقع. التقييم الشخصي للعلاج الطبيعي خطوة مناسبة.')}</div>}<div className="phase-history"><h3>{t('Your phase journey','رحلة مراحلك')}</h3>{['Calm','Load','Capacity'].map((p,i)=><div key={p}><span className={state.phase>=i+1?'history-dot filled':'history-dot'}/><strong>{t(p,['تهدئة','تحميل','قدرة'][i])}</strong><span>{state.phase===i+1?t('Building here','هنا الآن'):state.phase>i+1?t('Completed','مكتملة'):t('When you’re ready','حين تكون مستعداً')}</span></div>)}</div></>;
 const articles=[{title:t('Hurt doesn’t always mean harm.','الألم لا يعني دائماً الضرر.'),tag:t('UNDERSTANDING PAIN','فهم الألم'),text:t('Pain is real, but it is not a precise damage meter. The nervous system can become more protective after an injury or a long period of discomfort. Comfortable, repeatable movement helps it learn that you can move safely. New or worsening neurological symptoms are different: stop and get assessed.','الألم حقيقي لكنه ليس مقياساً دقيقاً للضرر. قد يصبح الجهاز العصبي أكثر حماية بعد الإصابة. تساعد الحركة المريحة المتكررة على استعادة الثقة. أوقف التمرين واطلب تقييماً عند ظهور أعراض عصبية جديدة أو متفاقمة.'),icon:Heart},{title:t('Your back is not fragile.','ظهرك ليس هشّاً.'),tag:t('MOVEMENT CONFIDENCE','الثقة بالحركة'),text:t('Your spine is built to bend, turn, and carry load. There is no single perfect posture, and changing position often matters more than sitting perfectly. Start with a movement that feels manageable, repeat it, and expand your range as confidence grows.','عمودك الفقري مصمّم للانحناء والدوران وتحمل الأحمال. لا توجد وضعية مثالية واحدة. تغيير الوضعية أهم من الجلوس المثالي. ابدأ بحركة مناسبة وزد النطاق تدريجياً.'),icon:Footprints},{title:t('A scan is not the whole story.','الصورة ليست القصة كاملة.'),tag:t('PUTTING THINGS IN PERSPECTIVE','وضع الأمور في سياقها'),text:t('Changes such as disc bulges and joint wear are common in people who have no pain at all. Imaging is useful for specific clinical questions, but it does not determine your future. How you move, sleep, recover and gradually load your body matters too.','تغيّرات مثل بروز الأقراص شائعة لدى أشخاص دون ألم. التصوير مفيد لأسئلة محددة لكنه لا يحدّد مستقبلك. الحركة والنوم والتعافي والحمل التدريجي مهمة أيضاً.'),icon:ScanLine},{title:t('Your own traffic light for movement.','إشارتك الخاصة للحركة.'),tag:t('EVERYDAY SELF-MANAGEMENT','إدارة يومية ذاتية'),text:t('Green: discomfort up to 4/10, settling within 24 hours, and no worse the next morning. Amber: the next-day response is not known yet — keep the dose steady and check in tomorrow. Red: pain above 4/10, symptoms that linger beyond a day, or a worse morning — ease off or swap down. New weakness or spreading numbness needs assessment.','أخضر: ألم حتى ٤/١٠ يهدأ خلال ٢٤ ساعة وليس أسوأ صباحاً. كهرماني: استجابة الغد غير معروفة، حافظ على الجرعة. أحمر: ألم فوق ٤/١٠ أو مستمر أو أسوأ صباحاً، خفف الحمل. الضعف الجديد والخدر الممتد يحتاجان تقييماً.'),icon:Activity}];
 const renderLearn=()=> <><div className="page-heading"><div><div className="eyebrow">{t('UNDERSTAND MORE. WORRY LESS.','افهم أكثر. اطمئن أكثر.')}</div><h1>{t('Knowledge is part of your recovery.','المعرفة جزء من تعافيك.')}</h1><p>{t('Small reads. A new way to think about your body.','قراءات قصيرة. طريقة جديدة لفهم جسمك.')}</p></div><BookOpen className="heading-icon" size={36} strokeWidth={1}/></div>{learnArticle!==null?<div className="article-detail"><button className="back-link" onClick={()=>setLearnArticle(null)}><ArrowLeft size={17}/>{t('All articles','جميع المقالات')}</button><span className="eyebrow">{articles[learnArticle].tag}</span><h1>{articles[learnArticle].title}</h1><p>{articles[learnArticle].text}</p><div className="notice"><Sparkles size={21}/>{t('Try one small, comfortable movement today. Confidence is something you practise.','جرّب حركة صغيرة ومريحة اليوم. الثقة تُبنى بالممارسة.')}</div><button className="primary-button" onClick={startSession}>{t('Put it into practice','حوّلها إلى ممارسة')}<ArrowRight size={17}/></button></div>:<><div className="featured-article" onClick={()=>setLearnArticle(0)} role="button" tabIndex={0} onKeyDown={e=>{if(e.key==='Enter')setLearnArticle(0);}}><div><span className="eyebrow">{t('A GOOD PLACE TO START · 2 MIN READ','بداية جيدة · دقيقتان للقراءة')}</span><h2>{articles[0].title}</h2><p>{t('Your pain is real. But it might not mean what you think it means.','ألمك حقيقي. لكنه قد لا يعني ما تتصوّره.')}</p><span className="text-button">{t('Let’s understand pain','لنفهم الألم')}<ArrowUpRight size={17}/></span></div><div className="learning-art"><Heart size={100} strokeWidth={.7}/><span className="art-orbit"/></div></div><div className="article-grid">{articles.slice(1).map((a,i)=><button className="article-card" key={a.title} onClick={()=>setLearnArticle(i+1)}><a.icon size={31} strokeWidth={1.2}/><span className="eyebrow">{a.tag}</span><h3>{a.title}</h3><span>{t('2 min read','دقيقتان للقراءة')}<ArrowUpRight size={18}/></span></button>)}</div><div className="presentation-education"><span className="eyebrow">{t('A LITTLE MORE ABOUT YOUR PATTERN','المزيد عن نمط ألمك')}</span><h2>{arabic?currentPresentation.nameAr:currentPresentation.name}</h2><p>{arabic?'الحركة المريحة والتحميل التدريجي مع مراقبة الأعراض يدعمان التعافي.':currentPresentation.explanation}</p><details><summary>{t('What helps, and what to expect','ما يساعد وما يمكن توقعه')}</summary><p>{currentPresentation.helps} {currentPresentation.course}</p></details></div></>}</>;
 return <div className="app-shell" dir={arabic?'rtl':'ltr'}><aside className="sidebar"><button className="brand" onClick={()=>navigate('body')} aria-label="Kinesio home"><span className="brand-mark"><i/><i/><i/><i/></span>kinē<span className="brand-period">.</span></button><div className="brand-caption">{t('MOVE TOWARDS BETTER','تحرّك نحو الأفضل')}</div><div className="nav-label">{t('YOUR RECOVERY','رحلتك للتعافي')}</div><nav>{navs.map(n=><button key={n.screen} className={(screen===n.screen||(n.screen==='body'&&assessmentScreens.includes(screen)))?'nav-item active':'nav-item'} onClick={()=>navigate(n.screen)}><n.icon size={19} strokeWidth={1.65}/><span>{t(n.label,n.ar)}</span>{n.screen==='body'&&<span className="nav-indicator"/>}</button>)}</nav><div className="sidebar-bottom"><div className="daily-reminder"><span className="reminder-art"><span/><span/><span/></span><span className="eyebrow">{t('ONE DAY AT A TIME','يوماً بيوم')}</span><h3>{t('Better is a direction.','الأفضل وجهة.')}</h3><p>{t('Not a deadline.','وليس موعداً نهائياً.')}</p><span className="reminder-line"/></div><button className="support-link" onClick={()=>setHelp(true)}><CircleHelp size={18}/>{t('A little guidance','القليل من الإرشاد')}<ArrowUpRight size={14}/></button><div className="sidebar-profile"><div className="avatar"><UserRound size={19}/></div><div><strong>{t('Your personal space','مساحتك الشخصية')}</strong><span><span className="live-dot"/>{t(sync==='synced'?'Progress saved':'Saved on this device',sync==='synced'?'تم حفظ التقدّم':'محفوظ على هذا الجهاز')}</span></div></div></div></aside><div className="main-shell"><header className="topbar"><div className="breadcrumb">{t('Your recovery','رحلتك للتعافي')}<ChevronRight size={13}/><span>{t(screenName,navs.find(n=>n.screen===screen)?.ar||'تقييمك الشخصي')}</span></div><div className="topbar-right"><span className="quiet-message"><span className="live-dot"/>{t('A little better, every day.','أفضل قليلاً، كل يوم.')}</span><button className="language-button" onClick={()=>setArabic(!arabic)}>{arabic?'العربية':'EN'}<ChevronDown size={12}/><span>{arabic?'English':'العربية'}</span></button><div className="top-avatar">{t('You','أنت')}</div></div></header><main className={`main-content screen-${screen}`}>{screen==='body'?renderBody():screen==='intake'?renderIntake():screen==='result'?renderResult():screen==='goal'?renderGoal():screen==='programme'?renderProgramme():screen==='home'?renderHome():screen==='session'?renderSession():screen==='checkin'?renderCheckin():screen==='progress'?renderProgress():renderLearn()}<footer className="page-footer"><span>kinē. <span>{t('A better relationship with your body.','علاقة أفضل مع جسمك.')}</span></span><span>{t('Thoughtfully built. Human by design.','صُمّم بعناية. من أجلك.')}</span></footer></main></div>{toast&&<div className="toast" role="status"><Check size={19}/><span>{toast}</span><button aria-label="Dismiss notification" onClick={()=>setToast('')}><X size={16}/></button></div>}{help&&<div className="modal-backdrop" onClick={()=>setHelp(false)}><div className="modal" role="dialog" aria-modal="true" aria-label="How it works" onClick={e=>e.stopPropagation()}><IconButton icon={X} label="Close guidance" onClick={()=>setHelp(false)}/><span className="round-feature"><Crosshair size={26}/></span><h2>{t('A starting point, in three small steps.','نقطة بداية في ثلاث خطوات صغيرة.')}</h2>{[[ScanLine,t('Show us where it hurts','حدّد موضع الألم'),t('Drag to rotate the body. Tap a region, then tap the exact spot to add a pin. Or use the region list.','اسحب لتدوير الجسم. اضغط على منطقة ثم الموضع الدقيق أو استخدم القائمة.')],[Settings2,t('Tell us a little more','أخبرنا بالمزيد'),t('Seven short questions help us choose the right kind of movement and the right dose.','سبعة أسئلة قصيرة تساعدنا على اختيار الحركة والجرعة المناسبتين.')],[Footprints,t('Take your next small step','خذ خطوتك التالية'),t('Follow a short session, check in, and let your response guide your progress.','اتبع جلسة قصيرة وسجّل استجابتك ودعها توجّه تقدّمك.')]].map(([I,title,sub])=>{const Icon=I as LucideIcon;return <div className="help-step" key={title as string}><Icon size={23}/><div><h3>{title as string}</h3><p>{sub as string}</p></div></div>;})}<button className="primary-button wide" onClick={()=>setHelp(false)}>{t('I’m ready','أنا مستعد')}<ArrowRight size={17}/></button></div></div>}{trafficOpen&&<div className="modal-backdrop"><div className="modal traffic-modal" role="dialog" aria-modal="true" aria-label="Your pain traffic light"><IconButton icon={X} label="Close" onClick={()=>setTrafficOpen(false)}/><span className="eyebrow">{t('BEFORE WE MOVE','قبل أن نتحرّك')}</span><h2>{t('Your body has a traffic light.','لجسمك إشارة مرور.')}</h2><p>{t('A little discomfort can be okay. Here’s how to listen.','قد يكون القليل من الانزعاج مقبولاً. إليك كيف تُنصت.')}</p><div className="traffic-rule green"><i/><div><strong>{t('Green · I can keep going','أخضر · يمكنني المتابعة')}</strong><p>{t('Up to 4/10, settles within 24 hours, and not worse the next morning.','حتى ٤/١٠، يهدأ خلال ٢٤ ساعة وليس أسوأ صباحاً.')}</p></div></div><div className="traffic-rule amber"><i/><div><strong>{t('Amber · I’ll check tomorrow','كهرماني · سأراقب غداً')}</strong><p>{t('Next-day response still unknown? Keep the dose steady. No need to push.','استجابة الغد غير معروفة؟ حافظ على الجرعة ولا تضغط على نفسك.')}</p></div></div><div className="traffic-rule red"><i/><div><strong>{t('Red · I’ll ease off','أحمر · سأخفف الحمل')}</strong><p>{t('Above 4/10, lingering beyond a day, or worse in the morning? Swap down or pause.','فوق ٤/١٠ أو مستمر أو أسوأ صباحاً؟ اختر بديلاً أسهل أو توقّف.')}</p></div></div><button className="primary-button wide" onClick={launchSession}>{t('Got it. Let’s move.','فهمت. لنتحرّك.')}<Play size={17}/></button></div></div>}</div>;
}
function FlagIcon(){return <Target size={30} strokeWidth={1.5}/>;}
